644	// strictCircuitObject decodes one committed circuit record's own member map,
645	// demanding a JSON object with exactly the known top-level fields once.
646	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
647		return strictObjectMembers(raw, what, persistCircuitFields)
648	}
649	
650	// strictObjectMembers decodes one committed record's own member map,
651	// demanding a JSON object without repeated keys. A non-nil allowed list
652	// restricts which keys may appear; nil allows any key. It scans only the
653	// record's own level: the envelope scanner already attributes a duplicated
654	// top-level key to this record, and nested values such as the constraint
655	// definition own their (more precise) strict decoders. Keys are compared
656	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
657	// still a duplicate, even when both values are identical.
658	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
659		trimmed := bytes.TrimSpace(raw)
660		if len(trimmed) == 0 || trimmed[0] != '{' {
661			return nil, corruptf("%s must be a JSON object", what)
662		}
663		dec := json.NewDecoder(bytes.NewReader(trimmed))
664		dec.UseNumber()
665		open, err := dec.Token()
666		if err != nil || open != json.Delim('{') {
667			return nil, corruptf("%s must be a JSON object", what)
668		}
669		var allowed map[string]bool
670		if allowedFields != nil {
671			allowed = make(map[string]bool, len(allowedFields))
672			for _, f := range allowedFields {
673				allowed[f] = true
674			}
675		}
676		members := make(map[string]json.RawMessage)
677		for dec.More() {
678			keyTok, err := dec.Token()
679			if err != nil {
680				return nil, corruptf("%s is not valid JSON: %v", what, err)
681			}
682			key, ok := keyTok.(string)
683			if !ok {
684				return nil, corruptf("%s is not valid JSON", what)
685			}
686			if allowed != nil && !allowed[key] {
687				return nil, corruptf("%s has unknown field %q", what, key)
688			}
689			if _, repeated := members[key]; repeated {
690				return nil, corruptf("%s contains duplicate field %q", what, key)
691			}
692			var value json.RawMessage
693			if err := dec.Decode(&value); err != nil {
694				return nil, corruptf("%s is not valid JSON: %v", what, err)
695			}
696			members[key] = value
697		}
698		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
699			return nil, corruptf("%s is not valid JSON", what)
700		}
701		if _, err := dec.Token(); err != io.EOF {
702			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
703		}
704		return members, nil
705	}
