723	
724	// compiledHashKey is the canonical spelling of a job record's
725	// compiled-artifact binding field.
726	const compiledHashKey = "compiled_hash"
727	
728	// isASCIIFoldOf reports whether key names canonical under an ASCII-only
729	// letter-case fold: the two must have the same byte length and every byte
730	// must match after mapping A-Z onto a-z. JSON keys arrive here already
731	// unescaped, so a key written with a \uXXXX escape for an ASCII letter (say
732	// u0076 for "v") is judged on its decoded spelling too. A key of a different
733	// length, or one that needs a non-ASCII rune to match, returns false — use
734	// strings.EqualFold to detect those non-ASCII lookalikes separately.
735	func isASCIIFoldOf(key, canonical string) bool {
736		if len(key) != len(canonical) {
737			return false
738		}
739		for i := 0; i < len(key); i++ {
740			c := key[i]
741			if c >= 'A' && c <= 'Z' {
742				c += 'a' - 'A'
743			}
744			if c != canonical[i] {
745				return false
746			}
747		}
748		return true
749	}
750	
751	// isCompiledHashKey reports whether key is an accepted spelling of the
752	// compiled-artifact binding field: only "compiled_hash" itself and ASCII
753	// letter-case variants such as "COMPILED_HASH" or "CoMpIlEd_HaSh". Keys are
754	// already JSON-unescaped at this point, so an escaped spelling of any of
755	// these forms lands here too. Non-ASCII letters are never folded here.
756	func isCompiledHashKey(key string) bool {
757		return isASCIIFoldOf(key, compiledHashKey)
758	}
759	
760	// jobVersionKey is the canonical spelling of a job record's pinned circuit
761	// version field. The version names the frozen circuit — and thereby its
762	// trusted setup and compiled artifact — the job belongs to.
763	const jobVersionKey = "version"
764	
765	// isJobVersionKey reports whether key names a job record's pinned circuit
766	// version field under any spelling the ordinary decode fills Version from:
767	// canonical "version", an ASCII letter-case variant such as "VERSION" or
768	// "VeRsIoN", or a JSON-escaped spelling that unescapes onto either (keys
769	// arrive here already unescaped). Because encoding/json's struct-tag matching
770	// folds with Unicode case rules (strings.EqualFold), the long-s "verſion"
771	// (U+017F, written directly or as the u017f escape) names the field too.
772	func isJobVersionKey(key string) bool {
773		return strings.EqualFold(key, jobVersionKey)
774	}
775	
776	// rejectAmbiguousJobVersion enforces the pinned-version uniqueness rule shared
777	// by the directory read (scanJobArrayDuplicates) and the single-record decode
778	// (persistJob.UnmarshalJSON): the version a job writes is the sole authority
779	// for which frozen circuit — and therefore which trusted setup and compiled
780	// artifact — the job belongs to, so one record may carry the field under at
781	// most one recognized spelling (isJobVersionKey). Two spellings on one record
782	// make the bound version depend on key order, since encoding/json keeps the
783	// last value, and corrupt the read: the whole record is refused whether the
784	// values agree or differ, whether both are legal versions, and whether
785	// unrelated members sit between them — neither value is ever picked to carry
786	// on. A single spelling of any recognized kind — including a lone long-s
787	// "verſion" — is the one version field and keeps its current reading.
788	//
789	// keys are the record's member keys in any order; the recognized spellings
790	// are filtered and sorted here so the message is deterministic. where names
791	// the record exactly as the calling read path already computes it (by id when
792	// known, else by position), so both paths locate the problem the same way.
793	func rejectAmbiguousJobVersion(where string, keys []string) error {
794		var versionKeys []string
795		for _, key := range keys {
796			if isJobVersionKey(key) {
797				versionKeys = append(versionKeys, key)
798			}
799		}
800		if len(versionKeys) <= 1 {
801			return nil
802		}
803		sort.Strings(versionKeys)
804		quoted := make([]string, len(versionKeys))
805		for i, k := range versionKeys {
806			quoted[i] = strconv.Quote(k)
807		}
808		return corruptf("%s carries the pinned version field %q more than once (as %s)",
809			where, jobVersionKey, strings.Join(quoted, ", "))
810	}
811	
812	// compiledHashLookalike reports a member key encoding/json would match onto
813	// the binding field's struct tag yet which is not an accepted ASCII spelling
814	// (isCompiledHashKey). Struct-tag matching in encoding/json folds with the
815	// Unicode simple case-folding rules (bytes.EqualFold), so a non-ASCII
816	// lookalike — "compiled_haſh" with U+017F long s, whether written directly
817	// or as the JSON escape u017f — silently fills CompiledHash and would let a
818	// damaged binding (null above all) read as unbound, then vanish on the next
819	// commit. Such a key is damage, regardless of its value or of a correctly
820	// spelled sibling key being present. Several aliases are reported in
821	// lexicographic order so the message is stable.
822	func compiledHashLookalike(members map[string]json.RawMessage) string {
823		var aliases []string
824		for key := range members {
825			if isCompiledHashKey(key) {
826				continue
827			}
828			if strings.EqualFold(key, compiledHashKey) {
829				aliases = append(aliases, key)
830			}
831		}
832		if len(aliases) == 0 {
833			return ""
834		}
835		sort.Strings(aliases)
836		return aliases[0]
837	}
838	
839	// Strict decoding of the compiled-artifact binding on a committed job record.
840	//
841	// compiled_hash is a field whose presence is meaningful: records written
842	// before bindings existed simply omit it, and an explicit "" is the unbound
843	// state. But once the key appears its value must be a JSON string. A null is
844	// not "no binding" — it is damage to a binding the record claims to carry,
845	// and so is a number, boolean, array or object in its place. Reading either
846	// as the zero string would silently turn a bound job into an unbound one
847	// (and the next commit would drop the field entirely), so the read is
848	// refused as data corruption instead. A repeated key — including one
849	// repeated through JSON string escapes, even with identical values — is
850	// likewise refused rather than resolved to its last value. A legal non-empty
851	// string keeps being matched against the pinned version's artifact by
852	// validateEnvelope, exactly as written.
853	//
854	// The field is recognized under any ASCII letter-case spelling, so a record
855	// carrying "COMPILED_HASH" (or any mixed-case form, escaped or not) is the
856	// same binding and follows the same rules: a single such key is read with
857	// the full string validation above, and two spellings of the field on one
858	// record — even with byte-identical values — are a duplicate binding and
859	// corrupt the read rather than being resolved by key order.
860	//
861	// Non-ASCII spellings are not accepted even though encoding/json itself
862	// would fold them onto the field: its struct-tag matching uses Unicode case
863	// folding, under which "compiled_haſh" (U+017F long s, written directly or
864	// as the JSON escape u017f) names CompiledHash just like "compiled_hash".
865	// Such a lookalike is damage to the binding the record claims to carry and
866	// is refused whatever its value — null, a legal hash or an explicit "" —
867	// and even when a correctly spelled "compiled_hash" sits beside it, in
868	// either key order and whether the two values agree. The damaged binding
869	// must never read as an unbound job and disappear on the next commit.
870	//
871	// The pinned version field is held to a uniqueness rule of its own, enforced
872	// through rejectAmbiguousJobVersion — the same rule the directory read
873	// applies, so a record is judged identically by both paths. Every spelling
874	// the ordinary decode below fills Version from counts as that one field
875	// (isJobVersionKey): canonical "version", an ASCII letter-case variant such
876	// as "VERSION", and, since struct-tag matching folds with Unicode case rules,
877	// the long-s "verſion" (U+017F, direct or u017f-escaped); keys are compared
878	// after JSON unescaping, so an escaped spelling lands here too. Two such
879	// spellings on one record are refused as data corruption whether the values
880	// agree or differ, whether both values are legal versions, and even when
881	// unrelated fields are interleaved between them. A non-ASCII "verſion" is
882	// refused only when another recognized spelling sits beside it; appearing by
883	// itself it is the single version field and keeps the current reading (the
884	// ordinary decode folds it onto Version). A single spelling of any kind keeps
885	// its current value and spelling compatibility, and an illegal single value —
886	// a string, a float, null, or a non-positive version — is rejected exactly as
887	// before, by the decode or validateEnvelope.
888	//
889	// Only these two job fields are judged here; every other field keeps the
890	// ordinary struct decoding.
891	func (j *persistJob) UnmarshalJSON(raw []byte) error {
892		const what = "stored job record"
893		if string(bytes.TrimSpace(raw)) == "null" {
894			return corruptf("%s must be a JSON object, not null", what)
895		}
896		// Name the job up front, best-effort, so a failure of the strict member
897		// walk below — an exact duplicate key is rejected there before a member map
898		// exists — still locates the record it came from. This probe only labels
899		// errors: a missing, non-string or undecodable id leaves the generic name,
900		// and the id is decoded for real by the ordinary pass later.
901		where := what
902		var idProbe struct {
903			ID string `json:"id"`
904		}
905		if err := json.Unmarshal(raw, &idProbe); err == nil && idProbe.ID != "" {
906			where = fmt.Sprintf("stored job record %q", idProbe.ID)
907		}
908		members, err := strictObjectMembers(raw, where, nil)
909		if err != nil {
910			return err
911		}
912		// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
913		// matching would silently read as this field ("compiled_haſh" with long
914		// s, directly written or ſ-escaped), whatever its value and whether
915		// or not a correctly spelled key accompanies it. It must never be ignored
916		// as an unknown member, which would let a damaged binding read unbound.
917		if alias := compiledHashLookalike(members); alias != "" {
918			return corruptf("%s carries the binding field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
919				where, compiledHashKey, alias)
920		}
921		// The pinned-version uniqueness rule, shared with the directory read
922		// (scanJobArrayDuplicates) through rejectAmbiguousJobVersion: a record
923		// carrying two recognized spellings of the version field is ambiguous —
924		// encoding/json keeps the last value, which would let the binding flip
925		// depending on key order (or let an unhashed job read against a different
926		// frozen, set-up version) — so the whole record is refused rather than
927		// resolved by order. A long-s spelling counts here only beside another
928		// recognized spelling; standing alone it is the single version field and
929		// keeps the current reading handled below.
930		memberKeys := make([]string, 0, len(members))
931		for key := range members {
932			memberKeys = append(memberKeys, key)
933		}
934		if err := rejectAmbiguousJobVersion(where, memberKeys); err != nil {
935			return err
936		}
937		// With zero or one recognized spelling, the ordinary decode below already
938		// yields the current value: a single canonical/ASCII/long-s spelling folds
939		// onto Version, and a missing version reads as 0 and is rejected by
940		// validateEnvelope as a job bound to an unknown circuit. Illegal single
941		// values (a string, a float, null, zero or negative) keep being rejected by
942		// that same decode or the envelope validation, so nothing is picked here.
943		// Every accepted spelling of the binding field counts as the same one
944		// field; the record may carry it at most once, however it is capitalized.
945		var bindingKeys []string
946		for key := range members {
947			if isCompiledHashKey(key) {
948				bindingKeys = append(bindingKeys, key)
949			}
950		}
951		if len(bindingKeys) > 1 {
952			sort.Strings(bindingKeys)
953			quoted := make([]string, len(bindingKeys))
954			for i, k := range bindingKeys {
955				quoted[i] = strconv.Quote(k)
956			}
957			return corruptf("%s carries the binding field %q more than once (as %s)",
958				where, compiledHashKey, strings.Join(quoted, ", "))
959		}
960		compiledHash := ""
961		hasBinding := false
962		if len(bindingKeys) == 1 {
963			hash, err := storedRecordShape.string(members[bindingKeys[0]], where+` field "compiled_hash"`)
964			if err != nil {
965				return err
966			}
967			compiledHash, hasBinding = hash, true
968		}
969		type plainJob persistJob
970		var decoded plainJob
971		if err := json.Unmarshal(raw, &decoded); err != nil {
972			return corruptf("%s is not valid JSON: %v", what, err)
973		}
974		if hasBinding {
975			decoded.CompiledHash = compiledHash
976		}
977		*j = persistJob(decoded)
978		return nil
979	}
980	
981	// Store is a persistent workbench backed by one local data directory.
982	//
983	// All operations are safe for concurrent use by multiple goroutines and by
984	// several processes pointed at the same directory: an in-process mutex plus a
985	// process-shared flock serialize commits, and every commit is an atomic
986	// temp-file/fsync/rename replacement. Open the directory with Open and call
987	// Close when done.
988	type Store struct {
989		dir  string
990		mu   sync.Mutex
991		lock *os.File
992	
993		data envelope
994	}
995	
996	// Open opens (creating if needed) the workbench data in dir. If the
997	// directory does not exist it is created. Existing committed data is loaded
998	// and fully validated before Open returns; on a corrupt, truncated or
999	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
1000	// leaves every file in the directory untouched.
1001	func Open(dir string) (*Store, error) {
1002		if dir == "" {
1003			return nil, invalidf("data directory must not be empty")
1004		}
1005		if err := os.MkdirAll(dir, 0o755); err != nil {
1006			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
1007		}
1008		lockPath := filepath.Join(dir, dirLockFile)
1009		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
1010		if err != nil {
1011			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
1012		}
1013		// Serialize against other processes while we read / validate.
1014		if err := lockExclusive(lock); err != nil {
1015			lock.Close()
1016			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
1017		}
1018	
1019		s := &Store{dir: dir, lock: lock}
1020		if err := s.loadLocked(); err != nil {
1021			unlockLock(lock)
1022			lock.Close()
1023			return nil, err
1024		}
1025		// The lock is taken again per operation; holding it for the store's
1026		// lifetime would forbid two open handles on one directory.
1027		if err := unlockLock(lock); err != nil {
1028			lock.Close()
1029			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
1030		}
1031		return s, nil
1032	}
1033	
1034	// Close releases the directory lock. It does not discard committed data.
1035	func (s *Store) Close() error {
1036		s.mu.Lock()
1037		defer s.mu.Unlock()
1038		if s.lock == nil {
1039			return nil
1040		}
1041		var first error
1042		if err := unlockLock(s.lock); err != nil {
1043			first = err
1044		}
1045		if err := s.lock.Close(); err != nil && first == nil {
1046			first = err
1047		}
1048		s.lock = nil
1049		return first
1050	}
1051	
1052	// Dir reports the data directory backing the store.
1053	func (s *Store) Dir() string { return s.dir }
1054	
1055	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
1056	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
1057	
1058	// loadLocked reads and validates the committed file. Caller must hold the
1059	// exclusive flock; the in-process mutex is taken by the public Open path.
1060	func (s *Store) loadLocked() error {
1061		raw, err := os.ReadFile(s.dataPath())
1062		if errors.Is(err, os.ErrNotExist) {
1063			s.data = envelope{Format: FormatVersion}
1064			return nil
1065		}
1066		if err != nil {
1067			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
1068		}
1069		if len(strings.TrimSpace(string(raw))) == 0 {
1070			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
1071		}
1072	
1073		var env envelope
1074		if err := json.Unmarshal(raw, &env); err != nil {
1075			// Shape failures surfaced by the persisted-definition decoders are
1076			// integrity failures, not JSON syntax errors; report their detail
1077			// instead of the generic "not valid JSON" wording.
1078			var se StoreError
1079			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
1080				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
1081			}
1082			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
1083		}
1084		if env.Format == 0 {
1085			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
1086		}
1087		if env.Format != FormatVersion {
1088			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
1089				s.dataPath(), env.Format, FormatVersion)
1090		}
1091		if err := validateEnvelope(env); err != nil {
1092			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
1093		}
1094		s.data = env
1095		return nil
1096	}
1097	
1098	// commitLocked writes the pending state atomically: temp file → fsync →
1099	// rename → fsync directory. Caller must hold both the in-process mutex and
1100	// the exclusive flock; all in-memory mutations must already have happened and
1101	// been rule-checked, so a failure here occurs before any success is reported.
1102	func (s *Store) commitLocked() error {
1103		s.data.Format = FormatVersion
1104		// Stable output: records are stored sorted so files are deterministic.
1105		sortEnvelope(&s.data)
1106	
1107		payload, err := json.MarshalIndent(&s.data, "", "  ")
1108		if err != nil {
1109			return fmt.Errorf("cannot encode data: %w", err)
1110		}
1111		payload = append(payload, '\n')
1112	
1113		tmp := s.tmpPath()
1114		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
1115		if err != nil {
1116			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
1117		}
1118		if _, err := f.Write(payload); err != nil {
1119			f.Close()
1120			os.Remove(tmp)
1121			return fmt.Errorf("cannot write staged data: %w", err)
1122		}
1123		if err := f.Sync(); err != nil {
1124			f.Close()
1125			os.Remove(tmp)
1126			return fmt.Errorf("cannot flush staged data: %w", err)
1127		}
1128		if err := f.Close(); err != nil {
1129			os.Remove(tmp)
1130			return fmt.Errorf("cannot finish staged data: %w", err)
1131		}
1132		if err := os.Rename(tmp, s.dataPath()); err != nil {
1133			os.Remove(tmp)
1134			return fmt.Errorf("cannot commit data file: %w", err)
1135		}
1136		if err := syncDir(s.dir); err != nil {
1137			// The rename already happened; lack of dir fsync only weakens crash
1138			// durability, never correctness of what is visible now.
1139			return nil
1140		}
1141		return nil
1142	}
1143	
1144	// withLock runs fn under the in-process mutex and an exclusive flock, then
1145	// atomically commits when fn requests it. The on-disk state is re-read after
1146	// acquiring the lock, so concurrent commits from another process or another
1147	// handle are always observed. Operations validate before mutating; a rejected
1148	// operation (commit=false or an error) writes nothing and leaves committed
1149	// state unchanged.
1150	func (s *Store) withLock(fn func() (commit bool, err error)) error {
1151		s.mu.Lock()
1152		defer s.mu.Unlock()
1153		if s.lock == nil {
1154			return invalidf("store is closed")
1155		}
1156		if err := lockExclusive(s.lock); err != nil {
1157			return fmt.Errorf("cannot lock data directory: %w", err)
1158		}
1159		defer unlockLock(s.lock)
1160	
1161		if err := s.loadLocked(); err != nil {
1162			return err
1163		}
1164		commit, err := fn()
1165		if err != nil {
1166			return err
1167		}
1168		if !commit {
1169			return nil
1170		}
1171		return s.commitLocked()
1172	}
1173	
1174	// withLockRead runs fn under a shared flock over freshly reloaded state.
1175	func (s *Store) withLockRead(fn func() error) error {
1176		s.mu.Lock()
1177		defer s.mu.Unlock()
1178		if s.lock == nil {
1179			return invalidf("store is closed")
1180		}
1181		if err := lockShared(s.lock); err != nil {
1182			return fmt.Errorf("cannot lock data directory: %w", err)
1183		}
1184		defer unlockLock(s.lock)
1185		if err := s.loadLocked(); err != nil {
1186			return err
1187		}
1188		return fn()
1189	}
1190	
1191	func sortEnvelope(env *envelope) {
1192		sort.Slice(env.Circuits, func(i, j int) bool {
1193			if env.Circuits[i].Name != env.Circuits[j].Name {
1194				return env.Circuits[i].Name < env.Circuits[j].Name
1195			}
1196			return env.Circuits[i].Version < env.Circuits[j].Version
1197		})
1198		sort.Slice(env.Setups, func(i, j int) bool {
1199			if env.Setups[i].Name != env.Setups[j].Name {
1200				return env.Setups[i].Name < env.Setups[j].Name
1201			}
1202			return env.Setups[i].Version < env.Setups[j].Version
1203		})
1204		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
1205		sort.Slice(env.Artifacts, func(i, j int) bool {
1206			if env.Artifacts[i].Name != env.Artifacts[j].Name {
1207				return env.Artifacts[i].Name < env.Artifacts[j].Name
1208			}
1209			return env.Artifacts[i].Version < env.Artifacts[j].Version
1210		})
1211	}
1212	
1213	// validateEnvelope re-checks every invariant on load so a tampered or
1214	// hand-edited file cannot bypass the domain rules.
1215	func validateEnvelope(env envelope) error {
1216		seenCircuit := make(map[[2]string]bool)
1217		circuitOK := make(map[[2]string]bool)
1218		for i, c := range env.Circuits {
1219			key := [2]string{c.Name, itoa(c.Version)}
1220			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
1221				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
1222			}
1223			if c.Version <= 0 {
1224				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
1225			}
1226			if seenCircuit[key] {
1227				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
1228			}
1229			seenCircuit[key] = true
1230			if c.Constraints <= 0 {
1231				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
1232			}
1233			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
1234				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
1235			}
1236			// The same representability rule the write path enforces: wire 0 plus
1237			// every declared input must fit inside the platform's int. A record
1238			// beyond that bound can never have been written by this build and
1239			// cannot be checked safely, so the directory is corrupt rather than
1240			// silently narrowed or read with a wrapped-around layout.
1241			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
1242				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
1243					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
1244			}
1245			if c.Definition != nil {
1246				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
1247					return err
1248				}
1249			}
1250			circuitOK[key] = true
1251		}
1252		seenSetup := make(map[[2]string]bool)
1253		for i, p := range env.Setups {
1254			key := [2]string{p.Name, itoa(p.Version)}
1255			if !circuitOK[key] {
1256				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
1257			}
1258			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
1259			if c == nil || !c.Frozen {
1260				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
1261			}
1262			if seenSetup[key] {
1263				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
1264			}
1265			seenSetup[key] = true
1266		}
1267		seenJob := make(map[string]bool)
1268		for i, j := range env.Jobs {
1269			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
1270				return fmt.Errorf("job #%d has an empty or blank id", i+1)
1271			}
1272			if seenJob[j.ID] {
1273				return fmt.Errorf("job %q appears more than once", j.ID)
1274			}
1275			seenJob[j.ID] = true
1276			if j.Kind != "prove" {
1277				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
1278			}
1279			if j.Attempt <= 0 {
1280				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
1281			}
1282			key := [2]string{j.Circuit, itoa(j.Version)}
1283			if !circuitOK[key] {
1284				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
1285			}
1286			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
1287			if c == nil || !c.Frozen {
1288				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
1289			}
1290			if !seenSetup[key] {
1291				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
1292			}
1293			// A recorded compiled-artifact binding must still resolve against the
1294			// pinned version's artifact; a dangling or mismatched binding makes
1295			// the file unreadable rather than silently dropping the binding.
1296			if j.CompiledHash != "" {
1297				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
1298				if artifact == nil {
1299					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
1300				}
1301				if artifact.Hash != j.CompiledHash {
1302					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
1303						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
1304				}
1305			}
1306		}
1307		seenArtifact := make(map[[2]string]bool)
1308		for i, a := range env.Artifacts {
1309			key := [2]string{a.Name, itoa(a.Version)}
1310			if !circuitOK[key] {
1311				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
1312			}
1313			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
1314			if c == nil || !c.Frozen {
1315				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
1316			}
1317			if seenArtifact[key] {
1318				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
1319			}
1320			seenArtifact[key] = true
1321			if c.Definition == nil {
1322				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
1323			}
1324			if a.Constraints != c.Constraints {
1325				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
1326					a.Name, a.Version, a.Constraints, c.Constraints)
1327			}
1328			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
1329			if err != nil {
1330				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
1331			}
1332			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
1333				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
1334			}
1335			wantHash := artifactHash(a.Name, a.Version, def)
1336			if a.Hash != wantHash {
1337				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
1338					a.Name, a.Version, a.Hash, wantHash)
1339			}
1340		}
1341		return nil
1342	}
1343	
1344	// validatePersistDefinition re-validates a stored definition against its
1345	// version's declared counts: prime modulus, in-range wires and an exact
1346	// constraint count match.
1347	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
1348		parsed, err := definitionFromPersist(*def, public, private)
1349		if err != nil {
1350			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
1351		}
1352		if !parsed.compatibleWith(constraints, public, private) {
1353			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
1354		}
1355		return nil
1356	}
1357	
1358	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
1359		for i := range cs {
1360			if cs[i].Name == name && cs[i].Version == version {
1361				return &cs[i]
1362			}
1363		}
1364		return nil
1365	}
1366	
1367	func itoa(v int) string { return fmt.Sprintf("%d", v) }
