9	// This file holds the domain operations of the persistent workbench. Every
10	// mutating operation validates its request before touching state, runs under
11	// the shared process lock and either commits one complete new state or
12	// commits nothing.
13	
14	// CreateCircuit creates a draft circuit version identified by Name+Version.
15	//
16	// The name must be non-empty and not only whitespace; Version must be
17	// positive; Constraints must be positive; the input counts must not be
18	// negative. Creating an already-existing version is idempotent when the
19	// description is identical (the stored record is returned unchanged); a
20	// differing description is reported as ErrConflict. Nothing about an
21	// existing version — frozen or not — is ever replaced by Create.
22	func (s *Store) CreateCircuit(c Circuit) (Circuit, error) {
23		if err := validateCircuitKey(c.Name, c.Version); err != nil {
24			return Circuit{}, err
25		}
26		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
27			return Circuit{}, err
28		}
29	
30		var result Circuit
31		err := s.withLock(func() (bool, error) {
32			if existing := findCircuit(s.data.Circuits, c.Name, c.Version); existing != nil {
33				if existing.Description != c.Description {
34					return false, conflictf("circuit %q version %d already exists with a different description", c.Name, c.Version)
35				}
36				result = circuitFromPersist(*existing)
37				return false, nil
38			}
39			record := persistCircuit{
40				Name: c.Name, Version: c.Version,
41				Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
42				Frozen: false, Description: c.Description,
43			}
44			s.data.Circuits = append(s.data.Circuits, record)
45			result = circuitFromPersist(record)
46			return true, nil
47		})
48		return result, err
49	}
